      await env.writeFile('apps/2048/widget.js', 'jsr.render(null);');
      // torn: manifest restored, entry lost
      await env.writeFile(
        'apps/todo/manifest.json',
        jsonEncode({'id': 'todo', 'name': 'Todo'}),
      );
