+  /// alnum plus dashes, starting with alnum. Every id minted by this
+  /// codebase (catalog install, graduation, dynamic widgets) conforms.
+  static final RegExp idPattern = RegExp(r'^[a-z0-9][a-z0-9-]{1,31}$');
