    }
    return '$root/$id';
  }

  /// Null-returning [appDir] for listing: null when [id] cannot resolve
  /// inside the namespace (the listing skips it — never listed, never
  /// startable).
  static String? tryAppDir(String id) =>
      isResolvableId(id) ? '$root/$id' : null;

