        .where((id) => !seen.contains(id))
        .toList();
    if (gone.isNotEmpty) {
      final installed = await _readInstalled();
      var pruned = false;
      for (final id in gone) {
        _manifestHashes.remove(id);
        _parsedApps.remove(id);
        _refHashes.remove(id);
        if (installed.remove(id) != null) pruned = true;
      }
