    } catch (_) {}
  }

  // No manifest — derive defaults from directory name.
  return WidgetManifest(
    id: id,
    name: _titleCase(id),
    description: '',
    version: defaultWidgetVersion,
    icon: '🔧',
    allowedCommands: const [],
    networkEnabled: true,
    widgetPath: normalized,
    isSingleFile: false,
